pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount == 0);
        // Record the caller as owner
        vm.prank(c.owner());
        // Expect revert when amount is 0
        vm.expectRevert();
        c.sendTo(receiver, amount);
        assertTrue(true);
    }
}

